local MillstoneCraneMaker = {}
local PRODUCTS = {
    iron_millstonecrane = { name = "Železni dvigalo za mlinske kamne", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni dvigalo za mlinske kamne za mlinarje." },
    bronze_millstonecrane = { name = "Bronast dvigalo za mlinske kamne", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast dvigalo za mlinske kamne za mlinarje." },
    silver_millstonecrane = { name = "Srebrn dvigalo za mlinske kamne", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn dvigalo za mlinske kamne za mlinarje." },
    gilded_millstonecrane = { name = "Pozlačen dvigalo za mlinske kamne", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen dvigalo za mlinske kamne za mlinarje." },
    jewel_set_millstonecrane = { name = "Draguljast dvigalo za mlinske kamne", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast dvigalo za mlinske kamne za mlinarje." },
    royal_sovereign_millstonecrane = { name = "Kraljevski suveren dvigalo za mlinske kamne", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren dvigalo za mlinske kamne z biseri za krono." },
}
local BUILDINGS = {
    millstonecrane_workshop = { name = "Millstonecrane delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    millstonecrane_house = { name = "Millstonecrane hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_millstonecrane_atelier = { name = "Mojstrski millstonecrane atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_millstonecrane_palace = { name = "Suverena millstonecrane palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillstoneCraneMaker.ironStock = 18; MillstoneCraneMaker.bronzeStock = 14; MillstoneCraneMaker.woodStock = 10; MillstoneCraneMaker.leatherStock = 8; MillstoneCraneMaker.silverStock = 8; MillstoneCraneMaker.goldStock = 6; MillstoneCraneMaker.jewelStock = 4; MillstoneCraneMaker.pearlStock = 4
MillstoneCraneMaker.productStock = {}; MillstoneCraneMaker.buildings = {}; MillstoneCraneMaker.maker = nil; MillstoneCraneMaker.activeMaking = {}; MillstoneCraneMaker.totalProducts = 0; MillstoneCraneMaker.dayTimer = 0
function MillstoneCraneMaker.init() MillstoneCraneMaker.ironStock=18; MillstoneCraneMaker.bronzeStock=14; MillstoneCraneMaker.woodStock=10; MillstoneCraneMaker.leatherStock=8; MillstoneCraneMaker.silverStock=8; MillstoneCraneMaker.goldStock=6; MillstoneCraneMaker.jewelStock=4; MillstoneCraneMaker.pearlStock=4; MillstoneCraneMaker.productStock={}; MillstoneCraneMaker.buildings={}; MillstoneCraneMaker.maker=nil; MillstoneCraneMaker.activeMaking={}; MillstoneCraneMaker.totalProducts=0; MillstoneCraneMaker.dayTimer=0; print("[MillstoneCraneMaker] Royal Millstone Crane Maker System initialized (6 products, 4 buildings)") end
function MillstoneCraneMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneCraneMaker.maker={name=n or ("Dvigalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dvigalec najet: %s (spretnost: %d)",MillstoneCraneMaker.maker.name,s),"success") end; return true end
function MillstoneCraneMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneCraneMaker.build(id) local ok,e=MillstoneCraneMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneCraneMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneCraneMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneCraneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneCraneMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneCraneMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneCraneMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneCraneMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneCraneMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneCraneMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneCraneMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneCraneMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneCraneMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneCraneMaker.buildings==0 then return false,"Potrebna dvigalna delavnica" end; if not MillstoneCraneMaker.maker then return false,"Potreben dvigalec" end; return true end
function MillstoneCraneMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneCraneMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneCraneMaker.ironStock=MillstoneCraneMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneCraneMaker.bronzeStock=MillstoneCraneMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneCraneMaker.woodStock=MillstoneCraneMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneCraneMaker.leatherStock=MillstoneCraneMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneCraneMaker.silverStock=MillstoneCraneMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneCraneMaker.goldStock=MillstoneCraneMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneCraneMaker.jewelStock=MillstoneCraneMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneCraneMaker.pearlStock=MillstoneCraneMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneCraneMaker.maker then t=math.max(1,t-math.floor(MillstoneCraneMaker.maker.skill/13)) end; table.insert(MillstoneCraneMaker.activeMaking,{id="millstonecrane_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneCraneMaker.completeMaking(m) local q=1.0+(MillstoneCraneMaker.getQualityBonus()/100); if MillstoneCraneMaker.maker then q=q+(MillstoneCraneMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneCraneMaker.productStock[m.productType]=(MillstoneCraneMaker.productStock[m.productType] or 0)+m.quantity; MillstoneCraneMaker.totalProducts=MillstoneCraneMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneCraneMaker.maker then MillstoneCraneMaker.maker.itemsMade=MillstoneCraneMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneCraneMaker.maker.skill=math.min(100,MillstoneCraneMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dvigalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonecrane.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneCraneMaker.update(dt) if not _G.state then return end; MillstoneCraneMaker.dayTimer=MillstoneCraneMaker.dayTimer+dt; if MillstoneCraneMaker.dayTimer>=30 then MillstoneCraneMaker.dayTimer=0; for i=#MillstoneCraneMaker.activeMaking,1,-1 do local m=MillstoneCraneMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneCraneMaker.completeMaking(m); table.remove(MillstoneCraneMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneCraneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneCraneMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneCraneMaker.getStats() return {ironStock=MillstoneCraneMaker.ironStock,bronzeStock=MillstoneCraneMaker.bronzeStock,woodStock=MillstoneCraneMaker.woodStock,leatherStock=MillstoneCraneMaker.leatherStock,silverStock=MillstoneCraneMaker.silverStock,goldStock=MillstoneCraneMaker.goldStock,jewelStock=MillstoneCraneMaker.jewelStock,pearlStock=MillstoneCraneMaker.pearlStock,productStock=MillstoneCraneMaker.productStock,numBuildings=#MillstoneCraneMaker.buildings,hasMaker=MillstoneCraneMaker.maker~=nil,makerName=MillstoneCraneMaker.maker and MillstoneCraneMaker.maker.name or "—",makerSkill=MillstoneCraneMaker.maker and MillstoneCraneMaker.maker.skill or 0,activeMaking=#MillstoneCraneMaker.activeMaking,totalProducts=MillstoneCraneMaker.totalProducts} end
return MillstoneCraneMaker
